const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cats=['Weddings','Pre-Wedding','Birthdays','Portraits','Engagements','Events','Maternity','Fashion & Creative'];
const img=(id,w=1400)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const samples=[['photo-1519741497674-611481863552','A day to remember','Weddings'],['photo-1511285560929-80b456fea0bc','Together, always','Pre-Wedding'],['photo-1530103862676-de8c9debad1d','A little celebration','Birthdays'],['photo-1508214751196-bcfd4ca60f91','In your own light','Portraits'],['photo-1511795409834-ef04bbd61622','The art of gathering','Events'],['photo-1523438885200-e635ba2c371e','The beginning of forever','Engagements']].map((p,i)=>({id:'sample-'+i,url:img(p[0]),title:p[1],category:p[2],description:p[1]+' — '+p[2]+' (illustrative photograph)',featured:true,published:true}));
let photos=[],events=[],settings={},filter='All',visible=[],lightIndex=0,session=null;

const connected=()=>true;
const toast=m=>{$('#toast').textContent=m;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',6000)};
function safeUrl(v){try{let u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
async function api(path,opts={}){const r=await fetch('/api'+path,{...opts,credentials:'same-origin',headers:{...(opts.body instanceof File?{}:{'Content-Type':'application/json'}),'X-Imagica-Request':'studio',...opts.headers}});if(!r.ok){const e=await r.json().catch(()=>({}));throw Error(e.message||'Request failed ('+r.status+')')}return r.status===204?null:r.json().catch(()=>null)}
const options=(selected='')=>cats.map(c=>`<option ${c===selected?'selected':''}>${c}</option>`).join('');
const booking=()=>settings.phone?`https://wa.me/${settings.phone.replace(/\D/g,'')}`:'/contact/';
const cta=()=>`<section class="cta"><span class="script">Your story deserves to be remembered</span><h2>Let’s create something<br><em>beautiful together.</em></h2><a class="button" href="/contact/">Let’s plan your shoot ↗</a></section>`;
const head=(tag,title,desc)=>`<div class="page-head"><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${desc}</p></div>`;
function photoGrid(items){return items.map(p=>`<button class="photo" data-photo="${esc(p.id)}" aria-label="View ${esc(p.title)}"><img src="${esc(safeUrl(p.url))}" alt="${esc(p.description||p.title)}" loading="lazy"><span>${esc(p.title)} <span class="eyebrow">${esc(p.category)}</span></span></button>`).join('')}
function eventCards(list){return list.length?`<div class="events-grid">${list.map(e=>`<article class="event">${e.cover_url?`<img src="${esc(safeUrl(e.cover_url))}" alt="${esc(e.title)}" loading="lazy">`:''}<small>${new Date(e.date).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kolkata'})} · ${new Date(e.date)<new Date()?'Completed':'Upcoming'}</small><h3>${esc(e.title)}</h3><p>${esc(e.location)}</p><p>${esc(e.description)}</p>${(e.images||[]).map(u=>`<a href="${esc(safeUrl(u))}" target="_blank" rel="noopener"><img src="${esc(safeUrl(u))}" alt="${esc(e.title)} event photograph" loading="lazy"></a>`).join('')}<a class="text-link" href="${booking()}">Ask about this event ↗</a></article>`).join('')}</div>`:'<div class="empty">New dates, new stories.<br>Upcoming sessions and events will be announced here.<br><a class="text-link" href="/contact/">Ask about availability ↗</a></div>'}
function home(){
 const collections=[{category:'Weddings',label:'Your forever, beautifully framed.',sample:samples[0]},{category:'Pre-Wedding',label:'A little adventure. A lot of love.',sample:samples[1]},{category:'Birthdays',label:'Big smiles. Little milestones.',sample:samples[2]},{category:'Portraits',label:'Simply, wonderfully you.',sample:samples[3]}];
 const pick=c=>photos.find(p=>p.category===c.category&&!p.id.startsWith('sample'))||c.sample;
 const selected=photos.filter(p=>p.featured);const frames=(selected.length?selected:photos).slice(0,4);
 const upcoming=events.filter(e=>new Date(e.date)>=new Date()).slice(0,3);
 const banners=[{category:'Weddings',tag:'For your once-in-a-lifetime',title:'Your moments.<br><em>Our imagination.</em>',text:'Turning your moments into timeless memories. Thoughtful photography for the stories closest to your heart.',photo:pick(collections[0])},{category:'Pre-Wedding',tag:'Before the big day',title:'A love story,<br><em>all your own.</em>',text:'Make time for the two of you. A relaxed pre-wedding session, filled with real connection and a little adventure.',photo:pick(collections[1])},{category:'Birthdays',tag:'For every beautiful milestone',title:'More joy.<br><em>More memories.</em>',text:'From birthday candles to family celebrations, keep the moments you wish could last a little longer.',photo:pick(collections[2])}];
 return '<div class="home-page">'+
 '<div class="home-banner" aria-label="Photography highlights" aria-roledescription="carousel">'+banners.map((b,i)=>
 '<article class="banner-frame" '+(i?'hidden':'')+' data-banner-frame="'+i+'" aria-label="'+(i+1)+' of 3: '+esc(b.category)+'">'+
 '<img class="banner-image" src="'+esc(b.photo.url)+'" alt="'+esc(b.photo.title)+'" '+(i?'loading="lazy"':'fetchpriority="high"')+'><div class="banner-shade"></div><div class="banner-copy"><span class="eyebrow">'+b.tag+'</span>'+(i?'<h2>':'<h1>')+b.title+(i?'</h2>':'</h1>')+'<p>'+b.text+'</p><div class="banner-actions"><a class="button" href="/gallery/?category='+encodeURIComponent(b.category)+'">Explore '+b.category+' ↗</a><a class="button outline" href="/contact/">Book a shoot ↗</a></div></div></article>').join('')+
 '<div class="banner-bottom"><span>WE BRING IMAGINATION INTO REALITY.</span><div class="banner-controls"><button type="button" data-banner-step="-1" aria-label="Previous banner">←</button><div class="banner-dots">'+banners.map((b,i)=>'<button type="button" data-banner-to="'+i+'" aria-label="Show '+esc(b.category)+' banner" aria-pressed="'+!i+'">'+String(i+1).padStart(2,'0')+'</button>').join('')+'</div><button type="button" data-banner-step="1" aria-label="Next banner">→</button></div></div></div>'+
 '<div class="home-intro-strip"><span>Weddings</span><span>Pre-Wedding</span><span>Birthdays</span><span>Portraits</span><span>Celebrations</span></div>'+
 '<section class="home-collections"><div class="section-title"><div><span class="eyebrow">Every chapter deserves a frame</span><h2>What are we <em>celebrating?</em></h2></div><p>Big days, quiet moments, and everything<br>that makes your story yours.</p></div><div class="home-category-grid">'+collections.map((c,i)=>{const p=pick(c);return '<a class="home-category" href="/gallery/?category='+encodeURIComponent(c.category)+'"><div class="home-category-image"><img src="'+esc(p.url)+'" alt="'+esc(p.title)+'" loading="lazy"><span class="category-arrow">↗</span></div><div class="category-caption"><span class="eyebrow">0'+(i+1)+'</span><div><h3>'+c.category+'</h3><p>'+c.label+'</p></div></div></a>'}).join('')+'</div></section>'+
 '<section class="home-story cream"><div class="home-story-images"><img class="story-main" src="'+img('photo-1511285560929-80b456fea0bc',1000)+'" alt="A quiet moment during a wedding celebration" loading="lazy"><img class="story-detail" src="'+img('photo-1452587925148-ce544e77e70d',600)+'" alt="A photographer looking through a camera" loading="lazy"><span class="story-signature script">Made of moments.</span></div><div class="home-story-copy"><span class="eyebrow">The heart behind Imagica</span><h2>A beautiful frame.<br><em>A feeling, forever.</em></h2><p>The laughter you couldn’t hold back. The glance only you noticed. The people who make a place feel like home.</p><p>At Imagica Portraits, we bring an artistic eye and a thoughtful approach to your story — with room to be yourself, and space for the unexpected.</p><a class="text-link" href="/about/">Meet the story behind the lens ↗</a></div></section>'+
 '<section class="home-selected"><div class="section-title"><div><span class="eyebrow">A few frames to fall in love with</span><h2>Moments worth <em>keeping.</em></h2></div><a class="text-link" href="/gallery/">Explore the complete gallery ↗</a></div><div class="home-selected-grid">'+frames.map(p=>'<button class="photo home-selected-photo" data-photo="'+esc(p.id)+'" aria-label="View '+esc(p.title)+'"><img src="'+esc(p.url)+'" alt="'+esc(p.description||p.title)+'" loading="lazy"><span>'+esc(p.title)+'<small>'+esc(p.category)+'</small></span></button>').join('')+'</div>'+(photos.some(p=>p.id.startsWith('sample'))?'<p class="sample">Illustrative photographs. Original studio collections appear here as they are published.</p>':'')+'</section>'+
 '<section class="home-process cream"><div><span class="eyebrow">From hello to a beautiful memory</span><h2>Let’s make it<br><em>feel like you.</em></h2><a class="text-link" href="/contact/">Start your story ↗</a></div><div class="process-steps"><article><span>01</span><div><h3>Tell us your idea.</h3><p>Share the occasion, your preferred date, and what you have in mind.</p></div></article><article><span>02</span><div><h3>Enjoy the moment.</h3><p>We’ll plan the details together and guide you through a relaxed session.</p></div></article><article><span>03</span><div><h3>Keep the feeling.</h3><p>Turn a fleeting chapter into photographs you can return to, again and again.</p></div></article></div></section>'+
 (upcoming.length?'<section><div class="section-title"><div><span class="eyebrow">On the calendar</span><h2>More stories <em>ahead.</em></h2></div><a class="text-link" href="/events/">View events ↗</a></div>'+eventCards(upcoming)+'</section>':'')+
 (settings.testimonial?'<section class="cta"><span class="eyebrow">Client stories</span><h2>“'+esc(settings.testimonial)+'”</h2><p>'+esc(settings.testimonialName)+'</p></section>':'')+
 '<section class="home-final"><span class="script">Some moments only happen once.</span><h2>Let’s make sure<br><em>you remember them.</em></h2><p>Your story. Our imagination. Something beautiful to keep.</p><a class="button" href="/contact/">Let’s plan your shoot ↗</a></section></div>';
}
function bindHomeBanners(){let current=0;const slides=[...document.querySelectorAll('[data-banner-frame]')];if(!slides.length)return;const show=n=>{current=(n+slides.length)%slides.length;slides.forEach((s,i)=>s.hidden=i!==current);document.querySelectorAll('[data-banner-to]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===current)))};document.querySelectorAll('[data-banner-to]').forEach(b=>b.onclick=()=>show(Number(b.dataset.bannerTo)));document.querySelectorAll('[data-banner-step]').forEach(b=>b.onclick=()=>show(current+Number(b.dataset.bannerStep)))}
function about(){return head('The heart behind the frame','Made with care.<br><em>Remembered with love.</em>','We Bring Imagination Into Reality.')+`<section class="story"><img src="${img('photo-1452587925148-ce544e77e70d',1000)}" alt="Behind the scenes with a camera" loading="lazy"><div><span class="eyebrow">Our story</span><h2>Good photographs begin<br>with <em>real connection.</em></h2><p>Imagica Portraits is a photography brand built around a simple idea: your moments deserve to be seen with care. We create thoughtful images of people, relationships, and celebrations.</p><p>Our approach blends an editorial eye with space for spontaneity. We’ll guide you when you need it, and let life unfold when the moment speaks for itself.</p><span class="script">With imagination, always.</span></div></section><section class="cream values"><article><span class="eyebrow">01 / Our mission</span><h3>Make the meaningful last.</h3><p>To turn fleeting moments into photographs you can return to, share, and treasure.</p></article><article><span class="eyebrow">02 / Our vision</span><h3>See the extraordinary.</h3><p>To find beauty in the ordinary and create space for every person’s unique story.</p></article><article><span class="eyebrow">03 / Our philosophy</span><h3>People before poses.</h3><p>Natural expression, considered light, and a calm experience from beginning to end.</p></article></section><section class="story"><div><span class="eyebrow">Your experience</span><h2>A thoughtful process.<br><em>A personal perspective.</em></h2><p>We start by listening. Together, we’ll talk through the occasion, the atmosphere, and the details that matter to you. Your session is shaped around your comfort and your story.</p>${settings.photographerName?`<h3>${esc(settings.photographerName)}</h3>`:""}<p>${esc(settings.studioBio||"Every shoot starts with a conversation. We take time to understand your plans, the people involved, and the moments you want to remember.")}</p></div><img src="${img('photo-1511285560929-80b456fea0bc',1000)}" alt="An intimate wedding moment" loading="lazy"></section>${cta()}`}
function gallery(){return head('The collections','Stories, <em>beautifully told.</em>','A celebration of love, life, and everything in between.')+`<section class="gallery-section"><div class="filters">${['All',...cats].map(c=>`<button class="filter ${filter===c?'active':''}" data-filter="${esc(c)}">${c}</button>`).join('')}</div><div class="gallery" id="gallery-grid"></div><p class="sample">${photos.some(p=>p.id.startsWith('sample'))?'Illustrative portfolio photographs. Original studio work will appear here after publication.':''}</p></section>${cta()}`}
function contact(){return head('Let’s begin','Your next chapter<br><em>starts with hello.</em>','Tell us what you’re dreaming of. We’ll help you bring it into focus.')+`<section class="contact-grid"><div><span class="eyebrow">We’d love to hear your story</span><h2>A moment worth<br><em>making time for.</em></h2><p>For weddings, portraits, birthdays, or a creative idea of your own, send a few details and let’s start planning.</p>${[['WhatsApp',settings.phone,booking()],['Email',settings.email,settings.email?'mailto:'+settings.email:''],['Instagram',settings.instagram,safeUrl(settings.instagram)],['Studio',settings.location,'']].map(([t,v,u])=>`<div class="contact-detail"><small>${t}</small>${v?(u?`<a href="${esc(u)}">${esc(v)} ↗</a>`:esc(v)):'Details will be announced soon.'}</div>`).join('')}</div><form id="inquiry"><div class="form-grid"><label>Your name<input name="name" required maxlength="100" autocomplete="name"></label><label>Phone number<input name="phone" required type="tel" maxlength="25" autocomplete="tel"></label><label>What are we celebrating?<select name="type">${options()}</select></label><label>Preferred date<input name="date" type="date" min="${new Date(Date.now()+19800000).toISOString().slice(0,10)}" required></label><label class="wide">Tell us a little more<textarea name="message" required maxlength="2000" placeholder="The place, the people, the feeling you have in mind…"></textarea></label></div><button class="button" type="submit">Send inquiry via WhatsApp ↗</button><p class="sample" style="text-align:left">Your message opens in WhatsApp for you to review and send.${settings.phone?'':' Booking opens once the studio configures its contact number.'}</p></form></section>`}
function render(){const path=location.pathname.replace(/\/$/,'')||'/';document.title=({ '/':'Home','/about':'About','/gallery':'Gallery','/events':'Events','/contact':'Contact','/admin':'Studio admin'}[path]||'Page not found')+' | Imagica Portraits';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.pathname.replace(/\/$/,'')===path));$('#main').innerHTML=path==='/'?home():path==='/about'?about():path==='/gallery'?gallery():path==='/events'?head('Gatherings & sessions','More moments<br><em>to look forward to.</em>','Discover upcoming sessions and revisit celebrations.')+`<section>${eventCards(events)}</section>`+cta():path==='/contact'?contact():path==='/admin'?admin():head('404','A frame <em>out of place.</em>','This page could not be found. <a href="/">Return home ↗</a>');if(path==='/gallery')updateGallery();bind();$('#floating').href=booking();$('#floating').textContent=settings.phone?'WhatsApp ↗':'Let’s talk ↗'}
function updateGallery(){visible=photos.filter(p=>filter==='All'||p.category===filter);$('#gallery-grid').innerHTML=visible.length?photoGrid(visible):'<div class="empty">This chapter is still being written.<br>New photographs will appear here soon.</div>';document.querySelectorAll('.filter').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter))}
function openPhoto(id){visible=photos.filter(p=>location.pathname.includes('gallery')?(filter==='All'||p.category===filter):true);lightIndex=visible.findIndex(p=>p.id===id);showLight();$('#lightbox').showModal()}
function showLight(){const p=visible[lightIndex];if(!p)return;$('#lightbox-img').src=p.url;$('#lightbox-img').alt=p.description||p.title;$('figcaption').textContent=p.title+' · '+p.category}
function bind(){bindHomeBanners();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;updateGallery()});$('#main').onclick=e=>{const b=e.target.closest('[data-photo]');if(b)openPhoto(b.dataset.photo)};const f=$('#inquiry');if(f)f.onsubmit=e=>{e.preventDefault();if(!settings.phone)return toast('The studio has not configured its WhatsApp number yet.');const d=new FormData(f);location.href=booking()+'?text='+encodeURIComponent(`Hello Imagica Portraits!\nName: ${d.get('name')}\nPhone: ${d.get('phone')}\nShoot: ${d.get('type')}\nPreferred date: ${d.get('date')}\n${d.get('message')}`)};if($('#admin-content'))loadAdmin().catch(e=>toast(e.message))}
function admin(){return head('Private studio','A space for <em>your stories.</em>','Manage the photographs and details your visitors see.')+`<div class="admin">${session?.admin?'<a id="logout" class="button small" href="/signout-with-chatgpt?return_to=%2Fadmin%2F" target="_top">Sign out</a><div id="admin-content"><p>Loading your studio…</p></div>':`<div class="panel" style="max-width:540px;margin:auto"><h3>Studio owner sign in</h3><p>Sign in with the ChatGPT account that owns this website. Only the authorized studio owner can upload or change content.</p>${session?.authenticated?'<p class="notice">The signed-in account is not the studio owner. Sign out and use the account that owns this site.</p><a class="button outline" href="/signout-with-chatgpt?return_to=%2Fadmin%2F" target="_top">Switch account</a>':'<a class="button" href="/signin-with-chatgpt?return_to=%2Fadmin%2F" target="_top">Sign in with ChatGPT ↗</a>'}</div>`}<aside class="admin-help"><span class="eyebrow">Your studio workflow</span><h3>Upload once. Share with everyone.</h3><ol><li>Sign in using the owner’s ChatGPT account.</li><li>Choose <strong>Upload photographs</strong>, then select an occasion such as Weddings or Birthdays.</li><li>Add a title and description, select JPG, PNG or WebP photos (up to 10 MB each), and check the previews.</li><li>Check <strong>Publish to public gallery</strong>, then upload. Your photographs are saved online and appear in the matching public category.</li><li>Use <strong>Gallery manager</strong> to edit, replace, feature or unpublish. Deleted items move to <strong>Trash</strong> and can be restored as drafts.</li><li>Use <strong>Events</strong> for dates, locations and event photos, and <strong>Site settings</strong> for WhatsApp and contact details.</li></ol><p>No separate website password or Supabase setup is needed.</p></aside></div>`}
async function upload(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024||!file.size)throw Error('Use JPG, PNG or WebP images up to 10 MB.');const key=crypto.randomUUID()+'.'+({'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type]);await api('/storage/v1/object/photos/'+key,{method:'POST',body:file,headers:{'Content-Type':file.type}});return location.origin+'/media/'+key}
async function loadAdmin(){const owner=await api('/rest/v1/admin_users?select=user_id');if(!owner.length){$('#admin-content').innerHTML='<p class="notice">This account does not have studio administrator access.</p>';return}const all=await api('/rest/v1/photos?select=*&order=created_at.desc'),ev=await api('/rest/v1/events?select=*&order=date.asc'),trash=await api('/admin/trash');$('#admin-content').innerHTML=`<div class="admin-tabs"><a href="#upload-panel" class="text-link">Upload photographs</a><a href="#manage-photos" class="text-link">Gallery manager</a><a href="#event-panel" class="text-link">Events</a><a href="#settings-panel" class="text-link">Site settings</a><a href="#trash-panel" class="text-link">Trash</a></div><form id="upload-form" class="panel"><h3 id="upload-panel">Publish a new collection</h3><label>Which category do these photographs belong to?<select name="category" required><option value="">Choose an occasion</option>${options()}</select></label><label>Collection / image title<input name="title" required maxlength="160"></label><label>Description / alt text<textarea name="description" required maxlength="1000"></textarea></label><label>Photographs (JPG, PNG, WebP · 10 MB each)<input type="file" id="photo-files" accept="image/jpeg,image/png,image/webp" multiple required></label><div class="preview" id="upload-preview"></div><label><input style="width:auto;display:inline" type="checkbox" name="featured"> Feature on homepage</label><label><input style="width:auto;display:inline" type="checkbox" name="published" checked> Publish to public gallery</label><progress id="upload-progress" value="0" max="100"></progress><button class="button">Upload photographs ↗</button></form><div class="panel"><h3 id="manage-photos">Gallery manager</h3><div class="admin-list">${all.map(p=>`<article><img src="${esc(p.url)}" alt="${esc(p.title)}"><form data-edit="${p.id}"><label>Title<input name="title" value="${esc(p.title)}" required maxlength="160"></label><label>Description<textarea name="description" maxlength="1000">${esc(p.description)}</textarea></label><label>Category<select name="category">${options(p.category)}</select></label><label><input style="width:auto;display:inline" name="featured" type="checkbox" ${p.featured?'checked':''}> Featured</label><label><input style="width:auto;display:inline" name="published" type="checkbox" ${p.published?'checked':''}> Published</label><label>Replace image<input name="replacement" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="button small">Save</button> <button type="button" class="danger" data-delete-photo="${p.id}">Delete</button></form></article>`).join('')||'<p>No uploads yet.</p>'}</div></div><form id="event-form" class="panel"><h3 id="event-panel">Create / edit an event</h3><input type="hidden" name="id"><label>Event title<input name="title" required maxlength="160"></label><div class="form-grid"><label>Date and time (India)<input name="date" type="datetime-local" required></label><label>Location<input name="location" required maxlength="300"></label></div><label>Description<textarea name="description" required maxlength="3000"></textarea></label><label>Cover image<input name="cover" type="file" accept="image/jpeg,image/png,image/webp"></label><label>Additional event images<input name="images" type="file" multiple accept="image/jpeg,image/png,image/webp"></label><div id="event-existing-images"></div><label><input style="width:auto;display:inline" name="published" type="checkbox" checked> Published</label><button class="button">Save event</button> <button type="reset" class="button outline">Clear</button><p class="sample">Upcoming / completed status is calculated from the event date.</p></form><div class="panel">${ev.map(e=>`<p>${esc(e.title)} · ${esc(e.date)} · ${e.published?'Published':'Draft'} <button data-edit-event="${e.id}">Edit</button> <button class="danger" data-delete-event="${e.id}">Delete</button></p>`).join('')||'No events yet.'}</div><form class="panel" id="settings-form"><h3 id="settings-panel">Contact & site settings</h3>${[['phone','WhatsApp number (country code, digits only)'],['email','Email'],['instagram','Instagram URL'],['location','Business location'],['testimonial','Client testimonial (publish only with consent)'],['testimonialName','Client attribution'],['photographerName','Photographer / studio team name'],['studioBio','About page studio biography']].map(([k,label])=>`<label>${label}<input name="${k}" value="${esc(settings[k]||'')}" maxlength="${k==='studioBio'?3000:1000}" ${k==='email'?'type="email"':k==='instagram'?'type="url"':''}></label>`).join('')}<button class="button">Save settings</button></form><div class="panel"><h3 id="trash-panel">Trash</h3><p>Deleted items are hidden from visitors. Restore an item as a draft, then publish it when ready.</p>${[...trash.photos.map(p=>({...p,type:"photos"})),...trash.events.map(p=>({...p,type:"events"}))].map(p=>`<p>${esc(p.title)} <button class="button small" data-restore="${p.id}" data-kind="${p.type}">Restore draft</button></p>`).join("")||"<p>Trash is empty.</p>"}</div>`;
document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{try{await api('/rest/v1/'+b.dataset.kind+'?id=eq.'+b.dataset.restore,{method:'PATCH',body:JSON.stringify({restore:true})});await loadData();await loadAdmin();toast('Restored as a draft.')}catch(e){toast(e.message)}});
$('#photo-files').onchange=e=>{const box=$('#upload-preview');box.querySelectorAll('img').forEach(i=>URL.revokeObjectURL(i.src));box.innerHTML='';[...e.target.files].forEach(f=>{const i=document.createElement('img');i.src=URL.createObjectURL(f);i.alt=f.name;box.append(i)})};
async function action(form,fn){const b=form.querySelector('button');b.disabled=true;try{await fn();toast('Saved successfully. Items marked Published are visible to visitors.');await loadData();await loadAdmin()}catch(e){toast(e.message)}finally{b.disabled=false}}
$('#upload-form').onsubmit=e=>{e.preventDefault();action(e.target,async()=>{const d=new FormData(e.target),files=[...$('#photo-files').files];for(let i=0;i<files.length;i++){const url=await upload(files[i]);await api('/rest/v1/photos',{method:'POST',body:JSON.stringify({url,title:d.get('title')+(files.length>1?' · '+(i+1):''),description:d.get('description'),category:d.get('category'),featured:d.has('featured'),published:d.has('published')})});$('#upload-progress').value=(i+1)/files.length*100}})};
document.querySelectorAll('[data-edit]').forEach(f=>f.onsubmit=e=>{e.preventDefault();action(f,async()=>{const d=new FormData(f),data={title:d.get('title'),description:d.get('description'),category:d.get('category'),featured:d.has('featured'),published:d.has('published')};if(d.get('replacement').size)data.url=await upload(d.get('replacement'));await api('/rest/v1/photos?id=eq.'+f.dataset.edit,{method:'PATCH',body:JSON.stringify(data)})})});
document.querySelectorAll('[data-delete-photo]').forEach(b=>b.onclick=async()=>{try{const p=all.find(p=>p.id===b.dataset.deletePhoto);await api('/rest/v1/photos?id=eq.'+p.id,{method:'DELETE'});await api('/storage/v1/object/photos',{method:'DELETE',body:JSON.stringify({prefixes:[p.url.split('/').pop()]})});await loadData();await loadAdmin();toast('Photograph moved to Trash.')}catch(e){toast(e.message)}});
document.querySelectorAll('[data-edit-event]').forEach(b=>b.onclick=()=>{const item=ev.find(e=>e.id===b.dataset.editEvent),f=$('#event-form');for(const k of ['id','title','location','description'])f.elements[k].value=item[k];f.elements.date.value=new Date(new Date(item.date).getTime()+19800000).toISOString().slice(0,16);f.elements.published.checked=item.published;$('#event-existing-images').innerHTML=(item.cover_url?`<label><input type="checkbox" name="removeCover" style="width:auto;display:inline"> Remove current cover</label>`:'')+(item.images||[]).map(u=>`<label><img src="${esc(u)}" alt="Event photograph" width="100" loading="lazy"><input type="checkbox" name="removeImage" value="${esc(u)}" style="width:auto;display:inline"> Remove this photo</label>`).join('');f.scrollIntoView({behavior:'smooth'})});
document.querySelectorAll('[data-delete-event]').forEach(b=>b.onclick=async()=>{try{await api('/rest/v1/events?id=eq.'+b.dataset.deleteEvent,{method:'DELETE'});await loadData();await loadAdmin();toast('Event moved to Trash.')}catch(e){toast(e.message)}});
$('#event-form').onreset=()=>{$('#event-existing-images').innerHTML=''};
$('#event-form').onsubmit=e=>{e.preventDefault();action(e.target,async()=>{const d=new FormData(e.target),id=d.get('id'),old=ev.find(e=>e.id===id),data={title:d.get('title'),date:new Date(d.get('date')+'+05:30').toISOString(),location:d.get('location'),description:d.get('description'),published:d.has('published'),cover_url:d.has('removeCover')?null:old?.cover_url||null,images:(old?.images||[]).filter(u=>!d.getAll('removeImage').includes(u))};if(d.get('cover').size)data.cover_url=await upload(d.get('cover'));for(const file of d.getAll('images'))if(file.size)data.images.push(await upload(file));await api('/rest/v1/events'+(id?'?id=eq.'+id:''),{method:id?'PATCH':'POST',body:JSON.stringify(data)})})};
$('#settings-form').onsubmit=e=>{e.preventDefault();action(e.target,async()=>{const data=Object.fromEntries(new FormData(e.target));if(data.phone&&!/^\d{8,15}$/.test(data.phone))throw Error('Enter 8–15 digits with country code for WhatsApp.');await api('/rest/v1/settings',{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body:JSON.stringify({id:1,data})})})}}
async function loadData(){const [p,e,s,me]=await Promise.all([api('/rest/v1/photos?select=*&published=eq.true&order=created_at.desc'),api('/rest/v1/events?select=*&published=eq.true&order=date.asc'),api('/rest/v1/settings?select=data&id=eq.1'),location.pathname.startsWith('/admin')?api('/me'):Promise.resolve(null)]);photos=p.length?p:samples;events=e;settings=s[0]?.data||{};if(me)session=me}
$('#menu').onclick=()=>{const open=$('nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open)};$('#year').textContent=new Date().getFullYear();$('#close-lightbox').onclick=()=>$('#lightbox').close();$('#prev').onclick=()=>{lightIndex=(lightIndex-1+visible.length)%visible.length;showLight()};$('#next').onclick=()=>{lightIndex=(lightIndex+1)%visible.length;showLight()};document.addEventListener('keydown',e=>{if($('#lightbox').open){if(e.key==='ArrowRight')$('#next').click();if(e.key==='ArrowLeft')$('#prev').click()}});filter=new URLSearchParams(location.search).get('category')||'All';if(!location.pathname.startsWith('/admin')){photos=samples;render()}loadData().then(render).catch(e=>{photos=[];render();toast('Content could not be loaded. Please try again later.')});
